OND.steps = [{"name":"calculation","family":"Calculations","summary":"One BigDFT calculation: an energy, at a fixed geometry.","words":"The first calculation of a study carries its settings. Any other one continues a step (``after``): it inherits every setting of that step and adds or changes some. After a relaxation it starts from the relaxed geometry.","params":[{"name":"after","link":true,"required":false,"default":null,"help":"the step this one continues. None for the first one."},{"name":"keys","link":false,"required":false,"default":null,"help":"input keys written directly, ``{\"dft\": {\"itermax\": 200}}``, for what no input action covers."}],"kind":"calculation"},{"name":"relax","family":"Calculations","summary":"Relax the geometry: move the atoms until the forces vanish.","words":"Continues a calculation with the same settings and optimises its geometry. The steps that continue a relaxation start from the geometry it ended on.","params":[{"name":"after","link":true,"required":false,"default":null,"help":"the calculation whose settings and geometry are taken."},{"name":"method","link":false,"required":false,"default":"SQNM","help":"optimiser. SQNM suits molecules."},{"name":"nsteps","link":false,"required":false,"default":300,"help":"maximum number of steps."},{"name":"forcemax","link":false,"required":false,"default":0.0002,"help":"stop when the largest force is below this, in Ha/bohr."},{"name":"keys","link":false,"required":false,"default":null,"help":"input keys written directly."}],"kind":"relax"},{"name":"ionised","family":"Pre-filled calculations","summary":"The same system with an electron removed: the partner of an ionisation energy.","words":"A calculation that continues ``after`` with another total charge. Removing one electron from a closed shell leaves one unpaired electron, so the calculation is spin-polarised.","params":[{"name":"after","link":true,"required":true,"default":null,"help":"the neutral calculation, or its relaxation."},{"name":"charge","link":false,"required":false,"default":1,"help":"total charge. +1 removes one electron."},{"name":"unpaired","link":false,"required":false,"default":1,"help":"number of unpaired electrons; it must have the parity of the electron count."}],"kind":"calculation","fills":{"actions":{"charge":1,"spin_polarize":1},"keys":{}}},{"name":"triplet","family":"Pre-filled calculations","summary":"The lowest triplet state: two unpaired electrons, and the settings a triplet needs.","words":"A calculation that continues ``after`` with two unpaired electrons. It arrives with what triplets were found to need: more iterations and restarts than the defaults allow, and a tighter criterion, without which runs on neighbouring grids can stop on different electronic states while each reports convergence.","params":[{"name":"after","link":true,"required":true,"default":null,"help":"the singlet calculation, or its relaxation."}],"kind":"calculation","fills":{"actions":{"spin_polarize":2,"set_scf_convergence":{"gnrm":1e-05}},"keys":{"dft":{"itermax":200,"nrepmax":5}}}},{"name":"hybrid","family":"Pre-filled calculations","summary":"The same calculation with a hybrid functional, at the same geometry.","words":"Hybrids cost much more than PBE: the usual practice is to relax with PBE and compute the energy with the hybrid there. The pseudopotentials are the PBE ones, named for each element, since none is registered for a hybrid.","params":[{"name":"after","link":true,"required":true,"default":null,"help":"the calculation or the relaxation to recompute."},{"name":"xc","link":false,"required":false,"default":"PBE0","help":"\"PBE0\", \"B3LYP\" or \"HF\"."}],"kind":"calculation","fills":{"actions":{"set_xc":"PBE0"},"keys":{}}},{"name":"converge","family":"Series and decisions","summary":"Vary one setting of a calculation and see when the result stops changing.","words":"Runs the calculation ``of`` once per value. The values go from the cheapest to the most accurate: the last one is the reference. The step proposes the first value whose result is within ``within`` of the reference, and nothing if only the reference itself is: the series must then be extended. With ``relative_to``, what is watched is the difference between the two calculations, both varied: converge the quantity the study is about, which usually settles long before a total energy does.","params":[{"name":"of","link":true,"required":true,"default":null,"help":"the calculation to vary."},{"name":"action","link":false,"required":false,"default":"set_hgrid","help":"the input action whose argument is varied."},{"name":"values","link":false,"required":false,"default":[0.5,0.45,0.4,0.35],"help":"its values, from the cheapest to the most accurate."},{"name":"within","link":false,"required":false,"default":0.001,"help":"tolerance, in eV (per atom for a total energy)."},{"name":"relative_to","link":true,"required":false,"default":null,"help":"a second calculation; the criterion is then on E(of) - E(relative_to)."},{"name":"per_atom","link":false,"required":false,"default":true,"help":"divide a total energy by the number of atoms. Ignored with relative_to."}],"kind":"converge"},{"name":"choose","family":"Series and decisions","summary":"Decide on the value of a setting, for every step that follows.","words":"The series ``among`` proposes a value; this step retains one. Left alone it retains the proposal. A person may retain another value and say why: the reason is kept with the study. Every step defined after this one uses the retained value.","params":[{"name":"among","link":true,"required":true,"default":null,"help":"the convergence series the decision is taken on."},{"name":"retained","link":false,"required":false,"default":null,"help":"the value kept. None keeps what the series proposes."},{"name":"because","link":false,"required":false,"default":"","help":"the reason, when it is not the proposal."}],"kind":"choose"},{"name":"difference","family":"Results","summary":"The energy of one step minus the energy of another.","words":"","params":[{"name":"a","link":true,"required":true,"default":null,"help":"first calculation or relaxation."},{"name":"b","link":true,"required":true,"default":null,"help":"the one subtracted."},{"name":"unit","link":false,"required":false,"default":"eV","help":"\"eV\", \"kJ/mol\" or \"Ha\"."},{"name":"against","link":true,"required":false,"default":null,"help":"a target to judge the result with."}],"kind":"difference"},{"name":"target","family":"Results","summary":"A reference value and the window that counts as agreement, set before computing.","words":"","params":[{"name":"value","link":false,"required":true,"default":null,"help":"the reference, from experiment or from another calculation."},{"name":"within","link":false,"required":true,"default":null,"help":"half-width of the window."},{"name":"unit","link":false,"required":false,"default":"eV","help":"\"eV\", \"kJ/mol\" or \"Ha\"."},{"name":"source","link":false,"required":false,"default":"","help":"where the value comes from."}],"kind":"target","note":"target() missing 2 required positional arguments: 'value' and 'within'"}];
